"""
Goal of this file is to find all the valid audio files and making sure they are 30s long
"""

import os
import glob

import librosa


# File paths for easier calls
script_dir = os.path.dirname(os.path.abspath(__file__))
PATH_DATA = os.path.normpath(os.path.join(script_dir, "..", "..", "data"))
PATH_FMA_AUDIO = os.path.join(PATH_DATA, "fma_small_audio")

# Function generated by claude code, model Opus 5.5
# Prompt: Create a funtion that goes through all the songs in fma_small_audio and make sure that they are 30s long
# Additional note: This also found corrupted audio files by liberosa's get_duration function 
def check_song_length(root=PATH_FMA_AUDIO, target=30.0, tolerance=0.5):
    """
    Check every mp3 under root/<folder>/<track>.mp3 is ~target seconds long.

    Returns a list of (path, duration) for songs that are NOT within
    target +/- tolerance. duration is None if the file could not be read.
    """
    paths = sorted(glob.glob(os.path.join(root, "*", "*.mp3")))
    bad = []

    for path in paths:
        try:
            duration = librosa.get_duration(path=path)
        except Exception:
            bad.append((path, None))
            continue

        if abs(duration - target) > tolerance:
            bad.append((path, duration))

    print(f"Checked {len(paths)} songs, {len(bad)} not ~{target}s long")
    return bad


if __name__ == "__main__":
    bad_audio = []
    bad_audio.extend(check_song_length())

    if len(bad_audio) != 0:
        for path,song_id in bad_audio:
            print(os.path.relpath(path, PATH_FMA_AUDIO))
    